def marca_cabecalho(altura: int = 72) -> ft.Control:
    """Logotipo para o cabeçalho das telas (placa creme, proporção mantida)."""
    return ft.Container(
        bgcolor=COR_FUNDO_CABECALHO,
        border_radius=8,
        padding=6,
        content=ft.Image(src=LOGO_CABECALHO_B64, height=altura),  # largura automática: mantém a proporção
    )


def marca_login(altura: int = 190) -> ft.Control:
    """Logotipo da tela de login (placa creme, proporção mantida)."""
    return ft.Container(
        bgcolor=COR_FUNDO_LOGIN,
        border_radius=12,
        padding=12,
        content=ft.Image(src=LOGO_LOGIN_B64, height=altura),  # largura automática: mantém a proporção
    )
